<?php
/**
 * Plugin Name: KTD Dashboard Installer
 * Description: Installs the KTD Dashboard Home page template into your active theme and creates the Dashboard page.
 * Version: 1.0
 * Author: KTD
 */

if ( ! defined( 'ABSPATH' ) ) exit;

register_activation_hook( __FILE__, 'ktd_installer_activate' );
add_action( 'admin_init', 'ktd_installer_repair_dashboard_page_content' );

function ktd_installer_activate() {
    // 1. Write the template file into the active theme
    $theme_dir     = get_stylesheet_directory();
    $template_file = $theme_dir . '/template-ktd-dashboard.php';
    $b64           = ktd_get_template_b64();
    $decoded       = base64_decode( $b64 );

    if ( $decoded === false ) {
        wp_die( 'KTD Installer: Failed to decode template. Please contact support.' );
    }

    $result = file_put_contents( $template_file, $decoded );
    if ( $result === false ) {
        wp_die( 'KTD Installer: Could not write template file to ' . esc_html( $template_file ) . '. Check folder permissions.' );
    }

    // 2. Create the Dashboard page if it doesn't already exist
    $existing = get_posts( [
        'post_type'      => 'page',
        'post_status'    => 'publish',
        'posts_per_page' => 1,
        'meta_key'       => '_wp_page_template',
        'meta_value'     => 'template-ktd-dashboard.php',
    ] );

    $dashboard_page_id = 0;

    if ( empty( $existing ) ) {
        $page_id = wp_insert_post( [
            'post_title'   => 'Dashboard',
            'post_name'    => 'ktd-dashboard',
            'post_status'  => 'publish',
            'post_type'    => 'page',
            'post_content' => '',
        ] );

        if ( $page_id && ! is_wp_error( $page_id ) ) {
            update_post_meta( $page_id, '_wp_page_template', 'template-ktd-dashboard.php' );
            update_option( 'ktd_dashboard_page_id', $page_id );
            $dashboard_page_id = (int) $page_id;
        }
    } else {
        $dashboard_page_id = (int) $existing[0]->ID;
        update_option( 'ktd_dashboard_page_id', $dashboard_page_id );
    }

    // 3. Use Dashboard as homepage to avoid default WP sample pages.
    if ( $dashboard_page_id > 0 ) {
        update_option( 'show_on_front', 'page' );
        update_option( 'page_on_front', $dashboard_page_id );
        update_option( 'page_for_posts', 0 );

        // Clean default sample content created by fresh WordPress installs.
        $sample_page = get_page_by_path( 'sample-page', OBJECT, 'page' );
        if ( $sample_page && (int) $sample_page->ID !== $dashboard_page_id ) {
            wp_delete_post( (int) $sample_page->ID, true );
        }

        $hello_world_posts = get_posts( [
            'name'           => 'hello-world',
            'post_type'      => 'post',
            'post_status'    => 'any',
            'posts_per_page' => 5,
        ] );

        if ( is_array( $hello_world_posts ) ) {
            foreach ( $hello_world_posts as $post ) {
                if ( isset( $post->ID ) ) {
                    wp_delete_post( (int) $post->ID, true );
                }
            }
        }

        $default_posts = get_posts( [
            'post_type'      => 'post',
            'post_status'    => 'any',
            'posts_per_page' => 20,
        ] );

        if ( is_array( $default_posts ) ) {
            foreach ( $default_posts as $post ) {
                if ( ! isset( $post->ID, $post->post_title ) ) {
                    continue;
                }
                $title = strtolower( trim( (string) $post->post_title ) );
                if ( $title === 'hello world!' || $title === 'hello world' ) {
                    wp_delete_post( (int) $post->ID, true );
                }
            }
        }
    }
}

/**
 * If dashboard template code was accidentally pasted into page content,
 * clear it so the template can render normally.
 */
function ktd_installer_repair_dashboard_page_content() {
    if ( ! current_user_can( 'manage_options' ) ) {
        return;
    }

    $page_id = (int) get_option( 'ktd_dashboard_page_id' );

    if ( $page_id <= 0 ) {
        $existing = get_posts( [
            'post_type'      => 'page',
            'post_status'    => 'publish',
            'posts_per_page' => 1,
            'meta_key'       => '_wp_page_template',
            'meta_value'     => 'template-ktd-dashboard.php',
            'fields'         => 'ids',
        ] );

        if ( empty( $existing ) || ! isset( $existing[0] ) ) {
            return;
        }

        $page_id = (int) $existing[0];
        update_option( 'ktd_dashboard_page_id', $page_id );
    }

    if ( $page_id <= 0 ) {
        return;
    }

    $template = get_post_meta( $page_id, '_wp_page_template', true );
    if ( $template !== 'template-ktd-dashboard.php' ) {
        return;
    }

    $page = get_post( $page_id );
    if ( ! $page || ! isset( $page->post_content ) ) {
        return;
    }

    $content = (string) $page->post_content;
    if ( $content === '' ) {
        return;
    }

    $looks_like_template_code = (
        stripos( $content, '<?php' ) !== false ||
        stripos( $content, 'wp_get_current_user' ) !== false ||
        stripos( $content, 'display_name' ) !== false ||
        stripos( $content, 'KTD CRM' ) !== false
    );

    if ( ! $looks_like_template_code ) {
        return;
    }

    wp_update_post( [
        'ID'           => $page_id,
        'post_content' => '',
    ] );
}

// Admin notice after activation
add_action( 'admin_notices', 'ktd_installer_notice' );
function ktd_installer_notice() {
    $page_id = get_option( 'ktd_dashboard_page_id' );
    if ( ! $page_id ) return;
    $url = get_permalink( $page_id );
    echo '<div class="notice notice-success is-dismissible"><p>';
    echo '<strong>KTD Dashboard installed!</strong> ';
    echo 'Your dashboard page is ready: <a href="' . esc_url( $url ) . '" target="_blank">' . esc_html( $url ) . '</a>';
    echo '</p></div>';
}

function ktd_get_template_b64() {
    return '';
}
